private void update(Context context, AppWidgetManager appWidgetManager, int[] appWidgetIds, boolean privacyMode) {
    String snippet;
    PendingIntent pendingIntent;
    for (int i = 0; i < appWidgetIds.length; i++) {
        if (appWidgetIds[i] != 0) {
            int bgId = ResourceParser.getDefaultBgId(context);
            Intent intent = new Intent(context, (Class<?>) NoteEditActivity.class);
            intent.setFlags(536870912);
            intent.putExtra(Notes.INTENT_EXTRA_WIDGET_ID, appWidgetIds[i]);
            intent.putExtra(Notes.INTENT_EXTRA_WIDGET_TYPE, getWidgetType());
            Cursor c = getNoteWidgetInfo(context, appWidgetIds[i]);
            if (c != null && c.moveToFirst()) {
                if (c.getCount() > 1) {
                    Log.e(TAG, "Multiple message with same widget id:" + appWidgetIds[i]);
                    c.close();
                    return;
                } else {
                    snippet = c.getString(2);
                    bgId = c.getInt(1);
                    intent.putExtra("android.intent.extra.UID", c.getLong(0));
                    intent.setAction("android.intent.action.VIEW");
                }
            } else {
                snippet = context.getResources().getString(R.string.widget_havenot_content);
                intent.setAction("android.intent.action.INSERT_OR_EDIT");
            }
            if (c != null) {
                c.close();
            }
            RemoteViews rv = new RemoteViews(context.getPackageName(), getLayoutId());
            rv.setImageViewResource(R.id.widget_bg_image, getBgResourceId(bgId));
            intent.putExtra(Notes.INTENT_EXTRA_BACKGROUND_ID, bgId);
            if (privacyMode) {
                rv.setTextViewText(R.id.widget_text, context.getString(R.string.widget_under_visit_mode));
                pendingIntent = PendingIntent.getActivity(context, appWidgetIds[i], new Intent(context, (Class<?>) NotesListActivity.class), 201326592);
            } else {
                rv.setTextViewText(R.id.widget_text, snippet);
                pendingIntent = PendingIntent.getActivity(context, appWidgetIds[i], intent, 201326592);
            }
            rv.setOnClickPendingIntent(R.id.widget_text, pendingIntent);
            appWidgetManager.updateAppWidget(appWidgetIds[i], rv);
        }
    }
}
